// модуль (.mjs), значит строгий режим
const counter = {
  count: 0,
  inc() { this.count++; return this.count; },
};

counter.inc();             // 1
const inc = counter.inc;   // та же функция, но без "counter." при вызове
inc();                     // TypeError: Cannot read properties of undefined (reading 'count')
[1].forEach(counter.inc);  // та же ошибка: forEach вызывает колбэк как обычную функцию

inc.call(counter);                        // 2  явная привязка
const bound = counter.inc.bind(counter);
bound();                                  // 3
bound.call({ count: 100 });               // 4  bind сильнее call: {count:100} проигнорирован

function Point(x) { this.x = x; }
const BoundPoint = Point.bind({ ignored: true });
new BoundPoint(5);                        // Point { x: 5 }  new сильнее bind

function sloppy() { return this === globalThis; }  // файл без "use strict"
