// верхний уровень модуля: this === undefined
const obj = {
  name: "obj",
  arrow: () => this,                                 // this модуля, не obj
  regular() { return this.name; },
  later() { return [1, 2].map(() => this.name); },   // стрелка берёт this из later
};
obj.arrow();     // undefined
obj.regular();   // "obj"
obj.later();     // [ "obj", "obj" ]

const arrow = () => 1;
"prototype" in arrow;   // false
new arrow();            // TypeError: arrow is not a constructor

class User {
  static create(name) { return new User(name); }
  constructor(name) { this.name = name; }
  greet() { return "hi, " + this.name; }
}
const u = new User("Ann");

typeof User;                                       // "function"
Object.getPrototypeOf(u) === User.prototype;       // true
Object.hasOwn(u, "greet");                         // false: не на экземпляре
"greet" in u;                                      // true: нашёлся по цепочке
Object.getPrototypeOf(Object.prototype);           // null: конец цепочки
Object.keys(User.prototype);                       // []  методы неперечисляемые
User("x");  // TypeError: Class constructor User cannot be invoked without 'new'

// то же руками, как писали до ES2015
function OldUser(name) { this.name = name; }
OldUser.prototype.greet = function () { return "hi, " + this.name; };
Object.keys(OldUser.prototype);                    // [ "greet" ]  а тут перечисляемый

class Admin extends User {
  greet() { return super.greet() + " (admin)"; }
}
Object.getPrototypeOf(Admin.prototype) === User.prototype;  // true  (instance methods)
Object.getPrototypeOf(Admin) === User;                      // true  (static members)
Admin.create === User.create;                               // true
new Admin("Eve").greet();                                   // "hi, Eve (admin)"

class Button {
  label = "OK";
  handleClick = () => this.label;   // поле: своя функция у каждого экземпляра
  render() { return this.label; }   // метод: одна функция на прототипе
}
const a = new Button(), b = new Button();

a.handleClick === b.handleClick;          // false: две разные функции
a.render === b.render;                    // true: одна общая
Object.keys(a);                           // [ "label", "handleClick" ]
const cb = a.handleClick;  cb();          // "OK": this не теряется
const cb2 = a.render;      cb2();         // TypeError: ... reading 'label'

class FancyButton extends Button {
  handleClick = () => "fancy+" + super.handleClick();
}
new FancyButton().handleClick();   // TypeError: (intermediate value).handleClick is not a function

Button.prototype.render = () => "mocked";   // так подменяют методы в тестах
a.render();                                  // "mocked"
"handleClick" in Button.prototype;          // false: поле так не подменить

class Money { constructor(c) { this.cents = c; } format() { return "$" + this.cents / 100; } }
const state = {
  user: { name: "Ann", tags: ["a"] },
  createdAt: new Date("2026-01-01T00:00:00Z"),
  cache: new Map([["k", 1]]),
  note: undefined,
  price: new Money(1250),
};
state.self = state;                         // циклическая ссылка

const shallow = { ...state };
shallow.user.tags.push("b");
shallow.user === state.user;                // true
state.user.tags;                            // [ "a", "b" ]  оригинал изменился

const deep = structuredClone(state);
deep.user.tags.push("c");
state.user.tags;                            // [ "a", "b" ]  оригинал цел
deep.createdAt instanceof Date;             // true
deep.cache instanceof Map;                  // true
deep.self === deep;                         // true: цикл сохранён
"note" in deep;                             // true
deep.price instanceof Money;                // false: { cents: 1250 }, format потерян
structuredClone({ fn() {} });               // DataCloneError: fn() {} could not be cloned.

const { self, ...noCycle } = state;         // JSON не переживёт цикл
